<script setup>
import { ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';
import InputError from '@/Components/InputError.vue';
const props=defineProps({service:Object,plans:Array});
const form=useForm({plan_uuid:props.service.plan_uuid,auto_renew:props.service.auto_renew});
const action=ref(null);const reason=ref('');const canChangePlan=props.service.status==='active';
const submit=()=>form.put(route('portal.services.update',props.service.uuid));
const transition=()=>{if(reason.value.trim().length<5)return;const data={reason:reason.value};const options={onSuccess:()=>{action.value=null;reason.value='';}};action.value==='suspend'?router.post(route('portal.services.suspend',props.service.uuid),data,options):router.delete(route('portal.services.destroy',props.service.uuid),{...options,data});};
</script>
<template><Head :title="`Manage ${service.product}`"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="services"/></template><div class="mb-6"><p class="text-sm font-bold text-cyan-700">{{ service.number }} · {{ service.status }}</p><h1 class="mt-2 text-3xl font-bold">Manage {{ service.product }}</h1><p class="mt-2 text-slate-600">{{ service.customer }} · Current plan: {{ service.plan }}</p></div><p v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</p><form class="form-card" @submit.prevent="submit"><label>Plan<select v-model="form.plan_uuid" :disabled="!canChangePlan"><option v-for="plan in plans" :key="plan.uuid" :value="plan.uuid">{{ plan.name }} — {{ plan.currency }} {{ plan.price }} / {{ plan.billing_cycle }}</option></select><InputError :message="form.errors.plan_uuid"/><span v-if="!canChangePlan" class="mt-1 text-xs text-slate-500">Plan changes become available after the service is active.</span><span v-else class="mt-1 text-xs text-slate-500">Plan changes use the proration engine and are recorded in service history.</span></label><label class="mt-5 flex items-center gap-3"><input v-model="form.auto_renew" type="checkbox" class="rounded border-slate-300 text-[#0797A5] focus:ring-[#0797A5]"/><span>Automatically renew this service</span></label><div class="mt-6 flex gap-3"><button class="form-button" :disabled="form.processing">Save changes</button><Link :href="route('portal.services.index')" class="rounded-xl border px-6 py-3">Back</Link></div></form><section v-if="!['cancelled','expired'].includes(service.status)" class="mt-6 rounded-2xl border border-red-200 bg-white p-6"><h2 class="text-lg font-bold text-red-800">Service status</h2><p class="mt-1 text-sm text-slate-600">Suspension temporarily disables the service. Cancellation replaces deletion so invoices, licences, and audit history remain intact.</p><div class="mt-4 flex flex-wrap gap-3"><button v-if="service.status!=='suspended'" type="button" class="rounded-xl border border-amber-300 px-4 py-2 font-bold text-amber-800" @click="action='suspend'">Suspend service</button><button type="button" class="rounded-xl border border-red-300 px-4 py-2 font-bold text-red-700" @click="action='cancel'">Cancel service</button></div><div v-if="action" class="mt-4 rounded-xl bg-slate-50 p-4"><label class="font-semibold">Reason<textarea v-model="reason" rows="3" class="mt-2 w-full" placeholder="Please explain why you want to make this change."/></label><div class="mt-3 flex gap-3"><button type="button" class="rounded-lg bg-red-700 px-4 py-2 font-bold text-white disabled:opacity-50" :disabled="reason.trim().length<5" @click="transition">Confirm {{ action }}</button><button type="button" class="px-4 py-2 font-semibold" @click="action=null;reason=''">Keep service</button></div></div></section></PortalLayout></template>
